mapper.select:
SELECT mo.id AS id, mo.user_id AS user_id, u.name AS user_name, mo.app_id AS app_id, a.name AS app_name, mo.override_type AS override_type, mo.remark AS remark, mo.create_time AS create_time, mo.update_time AS update_time FROM tab_app_access_manual_override mo INNER JOIN tab_user u ON u.id = mo.user_id INNER JOIN tab_app a ON a.id = mo.app_id
AND mo.user_id = #{userId} AND mo.app_id = #{appId} AND mo.override_type = #{overrideType}
ORDER BY mo.id DESC
